def __init__(self, img_folder, ann_file, transforms):
    super().__init__(img_folder, ann_file)
    self._transforms = transforms

def __call__(self, image, target):
    for t in self.transforms:
        image, target = t(image, target)
    return image, target

def forward(
    self, image: Tensor, target: Optional[Dict[str, Tensor]] = None
) -> Tuple[Tensor, Optional[Dict[str, Tensor]]]:
    if torch.rand(1) < self.p:
        image = F.hflip(image)
        if target is not None:
            _, _, width = F.get_dimensions(image)
            target["boxes"][:, [0, 2]] = width - target["boxes"][:, [2, 0]]
            if "masks" in target:
                target["masks"] = target["masks"].flip(-1)
            if "keypoints" in target:
                keypoints = target["keypoints"]
                keypoints = _flip_coco_person_keypoints(keypoints, width)
                target["keypoints"] = keypoints
    return image, target

def forward(
    self, image: Tensor, target: Optional[Dict[str, Tensor]] = None
) -> Tuple[Tensor, Optional[Dict[str, Tensor]]]:
    image = F.pil_to_tensor(image)
    return image, target

def forward(
    self, image: Tensor, target: Optional[Dict[str, Tensor]] = None
) -> Tuple[Tensor, Optional[Dict[str, Tensor]]]:
    if not self.scale:
        return image.to(dtype=self.dtype), target
    image = F.convert_image_dtype(image, self.dtype)
    return image, target

def __init__(
    self, fill: Optional[List[float]] = None, side_range: Tuple[float, float] = (1.0, 4.0), p: float = 0.5
):
    super().__init__()
    if fill is None:
        fill = [0.0, 0.0, 0.0]
    self.fill = fill
    self.side_range = side_range
    if side_range[0] < 1.0 or side_range[0] > side_range[1]:
        raise ValueError(f"Invalid canvas side range provided {side_range}.")
    self.p = p

@torch.jit.unused

def forward(
    self, image: Tensor, target: Optional[Dict[str, Tensor]] = None
) -> Tuple[Tensor, Optional[Dict[str, Tensor]]]:
    if isinstance(image, torch.Tensor):
        if image.ndimension() not in {2, 3}:
            raise ValueError(f"image should be 2/3 dimensional. Got {image.ndimension()} dimensions.")
        elif image.ndimension() == 2:
            image = image.unsqueeze(0)

    if torch.rand(1) >= self.p:
        return image, target

    _, orig_h, orig_w = F.get_dimensions(image)

    r = self.side_range[0] + torch.rand(1) * (self.side_range[1] - self.side_range[0])
    canvas_width = int(orig_w * r)
    canvas_height = int(orig_h * r)

    r = torch.rand(2)
    left = int((canvas_width - orig_w) * r[0])
    top = int((canvas_height - orig_h) * r[1])
    right = canvas_width - (left + orig_w)
    bottom = canvas_height - (top + orig_h)

    if torch.jit.is_scripting():
        fill = 0
    else:
        fill = self._get_fill_value(F._is_pil_image(image))

    image = F.pad(image, [left, top, right, bottom], fill=fill)
    if isinstance(image, torch.Tensor):
        # PyTorch's pad supports only integers on fill. So we need to overwrite the colour
        v = torch.tensor(self.fill, device=image.device, dtype=image.dtype).view(-1, 1, 1)
        image[..., :top, :] = image[..., :, :left] = image[..., (top + orig_h) :, :] = image[
            ..., :, (left + orig_w) :
        ] = v

    if target is not None:
        target["boxes"][:, 0::2] += left
        target["boxes"][:, 1::2] += top

    return image, target

def forward(
    self, image: Tensor, target: Optional[Dict[str, Tensor]] = None
) -> Tuple[Tensor, Optional[Dict[str, Tensor]]]:
    if isinstance(image, torch.Tensor):
        if image.ndimension() not in {2, 3}:
            raise ValueError(f"image should be 2/3 dimensional. Got {image.ndimension()} dimensions.")
        elif image.ndimension() == 2:
            image = image.unsqueeze(0)

    r = torch.rand(7)

    if r[0] < self.p:
        image = self._brightness(image)

    contrast_before = r[1] < 0.5
    if contrast_before:
        if r[2] < self.p:
            image = self._contrast(image)

    if r[3] < self.p:
        image = self._saturation(image)

    if r[4] < self.p:
        image = self._hue(image)

    if not contrast_before:
        if r[5] < self.p:
            image = self._contrast(image)

    if r[6] < self.p:
        channels, _, _ = F.get_dimensions(image)
        permutation = torch.randperm(channels)

        is_pil = F._is_pil_image(image)
        if is_pil:
            image = F.pil_to_tensor(image)
            image = F.convert_image_dtype(image)
        image = image[..., permutation, :, :]
        if is_pil:
            image = F.to_pil_image(image)

    return image, target

def forward(
    self, image: Tensor, target: Optional[Dict[str, Tensor]] = None
) -> Tuple[Tensor, Optional[Dict[str, Tensor]]]:
    if isinstance(image, torch.Tensor):
        if image.ndimension() not in {2, 3}:
            raise ValueError(f"image should be 2/3 dimensional. Got {image.ndimension()} dimensions.")
        elif image.ndimension() == 2:
            image = image.unsqueeze(0)

    _, orig_height, orig_width = F.get_dimensions(image)

    scale = self.scale_range[0] + torch.rand(1) * (self.scale_range[1] - self.scale_range[0])
    r = min(self.target_size[1] / orig_height, self.target_size[0] / orig_width) * scale
    new_width = int(orig_width * r)
    new_height = int(orig_height * r)

    image = F.resize(image, [new_height, new_width], interpolation=self.interpolation, antialias=self.antialias)

    if target is not None:
        target["boxes"][:, 0::2] *= new_width / orig_width
        target["boxes"][:, 1::2] *= new_height / orig_height
        if "masks" in target:
            target["masks"] = F.resize(
                target["masks"],
                [new_height, new_width],
                interpolation=InterpolationMode.NEAREST,
                antialias=self.antialias,
            )

    return image, target

def _pad(self, img, target, padding):
    # Taken from the functional_tensor.py pad
    if isinstance(padding, int):
        pad_left = pad_right = pad_top = pad_bottom = padding
    elif len(padding) == 1:
        pad_left = pad_right = pad_top = pad_bottom = padding[0]
    elif len(padding) == 2:
        pad_left = pad_right = padding[0]
        pad_top = pad_bottom = padding[1]
    else:
        pad_left = padding[0]
        pad_top = padding[1]
        pad_right = padding[2]
        pad_bottom = padding[3]

    padding = [pad_left, pad_top, pad_right, pad_bottom]
    img = F.pad(img, padding, self.fill, self.padding_mode)
    if target is not None:
        target["boxes"][:, 0::2] += pad_left
        target["boxes"][:, 1::2] += pad_top
        if "masks" in target:
            target["masks"] = F.pad(target["masks"], padding, 0, "constant")

    return img, target

def __repr__(self) -> str:
    s = f"{self.__class__.__name__}(blending={self.blending}, resize_interpolation={self.resize_interpolation})"
    return s

def _get_iou_types(model):
    model_without_ddp = model
    if isinstance(model, torch.nn.parallel.DistributedDataParallel):
        model_without_ddp = model.module
    iou_types = ["bbox"]
    if isinstance(model_without_ddp, torchvision.models.detection.MaskRCNN):
        iou_types.append("segm")
    if isinstance(model_without_ddp, torchvision.models.detection.KeypointRCNN):
        iou_types.append("keypoints")
    return iou_types


