@staticmethod

def _cartesian_product(boxes1, boxes2, target_fn: Callable):
    N = boxes1.size(0)
    M = boxes2.size(0)
    result = torch.zeros((N, M))
    for i in range(N):
        for j in range(M):
            result[i, j] = target_fn(boxes1[i].unsqueeze(0), boxes2[j].unsqueeze(0))
    return result

