    def generate_tensor_with_range_type(shape, range_type, **kwargs):
        if range_type != "random_binary":
            low, high = {
                "small": (0.0, 0.2),
                "big": (0.8, 1.0),
                "zeros": (0.0, 0.0),
                "ones": (1.0, 1.0),
