def __init__(self, lambd):
    _log_api_usage_once(self)
    if not callable(lambd):
        raise TypeError(f"Argument lambd should be callable, got {repr(type(lambd).__name__)}")
    self.lambd = lambd

def __init__(self, transforms):
    _log_api_usage_once(self)
    if not isinstance(transforms, Sequence):
        raise TypeError("Argument transforms should be a sequence")
    self.transforms = transforms

def forward(self, img):
    if self.p < torch.rand(1):
        return img
    for t in self.transforms:
        img = t(img)
    return img

def __call__(self, img):
    order = list(range(len(self.transforms)))
    random.shuffle(order)
    for i in order:
        img = self.transforms[i](img)
    return img

def __init__(self, transforms, p=None):
    super().__init__(transforms)
    if p is not None and not isinstance(p, Sequence):
        raise TypeError("Argument p should be a sequence")
    self.p = p

def __call__(self, *args):
    t = random.choices(self.transforms, weights=self.p)[0]
    return t(*args)

def forward(self, img):
    """
    Args:
        img (PIL Image or Tensor): Image to be flipped.

    Returns:
        PIL Image or Tensor: Randomly flipped image.
    """
    if torch.rand(1) < self.p:
        return F.hflip(img)
    return img

def forward(self, img):
    """
    Args:
        img (PIL Image or Tensor): Image to be flipped.

    Returns:
        PIL Image or Tensor: Randomly flipped image.
    """
    if torch.rand(1) < self.p:
        return F.vflip(img)
    return img

def __init__(self, distortion_scale=0.5, p=0.5, interpolation=InterpolationMode.BILINEAR, fill=0):
    super().__init__()
    _log_api_usage_once(self)
    self.p = p

    if isinstance(interpolation, int):
        interpolation = _interpolation_modes_from_int(interpolation)

    self.interpolation = interpolation
    self.distortion_scale = distortion_scale

    if fill is None:
        fill = 0
    elif not isinstance(fill, (Sequence, numbers.Number)):
        raise TypeError("Fill should be either a sequence or a number.")

    self.fill = fill

def forward(self, img):
    """
    Args:
        img (PIL Image or Tensor): Image to be Perspectively transformed.

    Returns:
        PIL Image or Tensor: Randomly transformed image.
    """

    fill = self.fill
    channels, height, width = F.get_dimensions(img)
    if isinstance(img, Tensor):
        if isinstance(fill, (int, float)):
            fill = [float(fill)] * channels
        else:
            fill = [float(f) for f in fill]

    if torch.rand(1) < self.p:
        startpoints, endpoints = self.get_params(width, height, self.distortion_scale)
        return F.perspective(img, startpoints, endpoints, self.interpolation, fill)
    return img

@staticmethod

def __init__(self, transformation_matrix, mean_vector):
    super().__init__()
    _log_api_usage_once(self)
    if transformation_matrix.size(0) != transformation_matrix.size(1):
        raise ValueError(
            "transformation_matrix should be square. Got "
            f"{tuple(transformation_matrix.size())} rectangular matrix."
        )

    if mean_vector.size(0) != transformation_matrix.size(0):
        raise ValueError(
            f"mean_vector should have the same length {mean_vector.size(0)}"
            f" as any one of the dimensions of the transformation_matrix [{tuple(transformation_matrix.size())}]"
        )

    if transformation_matrix.device != mean_vector.device:
        raise ValueError(
            f"Input tensors should be on the same device. Got {transformation_matrix.device} and {mean_vector.device}"
        )

    if transformation_matrix.dtype != mean_vector.dtype:
        raise ValueError(
            f"Input tensors should have the same dtype. Got {transformation_matrix.dtype} and {mean_vector.dtype}"
        )

    self.transformation_matrix = transformation_matrix
    self.mean_vector = mean_vector

def _check_input(self, value, name, center=1, bound=(0, float("inf")), clip_first_on_zero=True):
    if isinstance(value, numbers.Number):
        if value < 0:
            raise ValueError(f"If {name} is a single number, it must be non negative.")
        value = [center - float(value), center + float(value)]
        if clip_first_on_zero:
            value[0] = max(value[0], 0.0)
    elif isinstance(value, (tuple, list)) and len(value) == 2:
        value = [float(value[0]), float(value[1])]
    else:
        raise TypeError(f"{name} should be a single number or a list/tuple with length 2.")

    if not bound[0] <= value[0] <= value[1] <= bound[1]:
        raise ValueError(f"{name} values should be between {bound}, but got {value}.")

    # if value is 0 or (1., 1.) for brightness/contrast/saturation
    # or (0., 0.) for hue, do nothing
    if value[0] == value[1] == center:
        return None
    else:
        return tuple(value)

@staticmethod

def forward(self, img):
    """
    Args:
        img (PIL Image or Tensor): Input image.

    Returns:
        PIL Image or Tensor: Color jittered image.
    """
    fn_idx, brightness_factor, contrast_factor, saturation_factor, hue_factor = self.get_params(
        self.brightness, self.contrast, self.saturation, self.hue
    )

    for fn_id in fn_idx:
        if fn_id == 0 and brightness_factor is not None:
            img = F.adjust_brightness(img, brightness_factor)
        elif fn_id == 1 and contrast_factor is not None:
            img = F.adjust_contrast(img, contrast_factor)
        elif fn_id == 2 and saturation_factor is not None:
            img = F.adjust_saturation(img, saturation_factor)
        elif fn_id == 3 and hue_factor is not None:
            img = F.adjust_hue(img, hue_factor)

    return img

def __init__(self, degrees, interpolation=InterpolationMode.NEAREST, expand=False, center=None, fill=0):
    super().__init__()
    _log_api_usage_once(self)

    if isinstance(interpolation, int):
        interpolation = _interpolation_modes_from_int(interpolation)

    self.degrees = _setup_angle(degrees, name="degrees", req_sizes=(2,))

    if center is not None:
        _check_sequence_input(center, "center", req_sizes=(2,))

    self.center = center

    self.interpolation = interpolation
    self.expand = expand

    if fill is None:
        fill = 0
    elif not isinstance(fill, (Sequence, numbers.Number)):
        raise TypeError("Fill should be either a sequence or a number.")

    self.fill = fill

@staticmethod

def forward(self, img):
    """
    Args:
        img (PIL Image or Tensor): Image to be rotated.

    Returns:
        PIL Image or Tensor: Rotated image.
    """
    fill = self.fill
    channels, _, _ = F.get_dimensions(img)
    if isinstance(img, Tensor):
        if isinstance(fill, (int, float)):
            fill = [float(fill)] * channels
        else:
            fill = [float(f) for f in fill]
    angle = self.get_params(self.degrees)

    return F.rotate(img, angle, self.interpolation, self.expand, self.center, fill)

def __init__(
    self,
    degrees,
    translate=None,
    scale=None,
    shear=None,
    interpolation=InterpolationMode.NEAREST,
    fill=0,
    center=None,
):
    super().__init__()
    _log_api_usage_once(self)

    if isinstance(interpolation, int):
        interpolation = _interpolation_modes_from_int(interpolation)

    self.degrees = _setup_angle(degrees, name="degrees", req_sizes=(2,))

    if translate is not None:
        _check_sequence_input(translate, "translate", req_sizes=(2,))
        for t in translate:
            if not (0.0 <= t <= 1.0):
                raise ValueError("translation values should be between 0 and 1")
    self.translate = translate

    if scale is not None:
        _check_sequence_input(scale, "scale", req_sizes=(2,))
        for s in scale:
            if s <= 0:
                raise ValueError("scale values should be positive")
    self.scale = scale

    if shear is not None:
        self.shear = _setup_angle(shear, name="shear", req_sizes=(2, 4))
    else:
        self.shear = shear

    self.interpolation = interpolation

    if fill is None:
        fill = 0
    elif not isinstance(fill, (Sequence, numbers.Number)):
        raise TypeError("Fill should be either a sequence or a number.")

    self.fill = fill

    if center is not None:
        _check_sequence_input(center, "center", req_sizes=(2,))

    self.center = center

@staticmethod

def forward(self, img):
    """
        img (PIL Image or Tensor): Image to be transformed.

    Returns:
        PIL Image or Tensor: Affine transformed image.
    """
    fill = self.fill
    channels, height, width = F.get_dimensions(img)
    if isinstance(img, Tensor):
        if isinstance(fill, (int, float)):
            fill = [float(fill)] * channels
        else:
            fill = [float(f) for f in fill]

    img_size = [width, height]  # flip for keeping BC on get_params call

    ret = self.get_params(self.degrees, self.translate, self.scale, self.shear, img_size)

    return F.affine(img, *ret, interpolation=self.interpolation, fill=fill, center=self.center)

def __init__(self, p=0.5, scale=(0.02, 0.33), ratio=(0.3, 3.3), value=0, inplace=False):
    super().__init__()
    _log_api_usage_once(self)
    if not isinstance(value, (numbers.Number, str, tuple, list)):
        raise TypeError("Argument value should be either a number or str or a sequence")
    if isinstance(value, str) and value != "random":
        raise ValueError("If value is str, it should be 'random'")
    if not isinstance(scale, Sequence):
        raise TypeError("Scale should be a sequence")
    if not isinstance(ratio, Sequence):
        raise TypeError("Ratio should be a sequence")
    if (scale[0] > scale[1]) or (ratio[0] > ratio[1]):
        warnings.warn("Scale and ratio should be of kind (min, max)")
    if scale[0] < 0 or scale[1] > 1:
        raise ValueError("Scale should be between 0 and 1")
    if p < 0 or p > 1:
        raise ValueError("Random erasing probability should be between 0 and 1")

    self.p = p
    self.scale = scale
    self.ratio = ratio
    self.value = value
    self.inplace = inplace

@staticmethod

def forward(self, img):
    """
    Args:
        img (Tensor): Tensor image to be erased.

    Returns:
        img (Tensor): Erased Tensor image.
    """
    if torch.rand(1) < self.p:

        # cast self.value to script acceptable type
        if isinstance(self.value, (int, float)):
            value = [float(self.value)]
        elif isinstance(self.value, str):
            value = None
        elif isinstance(self.value, (list, tuple)):
            value = [float(v) for v in self.value]
        else:
            value = self.value

        if value is not None and len(value) not in (1, img.shape[-3]):
            raise ValueError(
                "If value is a sequence, it should have either a single value or "
                f"{img.shape[-3]} (number of input channels)"
            )

        x, y, h, w, v = self.get_params(img, scale=self.scale, ratio=self.ratio, value=value)
        return F.erase(img, x, y, h, w, v, self.inplace)
    return img

def __init__(self, kernel_size, sigma=(0.1, 2.0)):
    super().__init__()
    _log_api_usage_once(self)
    self.kernel_size = _setup_size(kernel_size, "Kernel size should be a tuple/list of two integers")
    for ks in self.kernel_size:
        if ks <= 0 or ks % 2 == 0:
            raise ValueError("Kernel size value should be an odd and positive number.")

    if isinstance(sigma, numbers.Number):
        if sigma <= 0:
            raise ValueError("If sigma is a single number, it must be positive.")
        sigma = (sigma, sigma)
    elif isinstance(sigma, Sequence) and len(sigma) == 2:
        if not 0.0 < sigma[0] <= sigma[1]:
            raise ValueError("sigma values should be positive and of the form (min, max).")
    else:
        raise ValueError("sigma should be a single number or a list/tuple with length 2.")

    self.sigma = sigma

@staticmethod

def __repr__(self) -> str:
    s = f"{self.__class__.__name__}(kernel_size={self.kernel_size}, sigma={self.sigma})"
    return s

def _setup_size(size, error_msg):
    if isinstance(size, numbers.Number):
        return int(size), int(size)

    if isinstance(size, Sequence) and len(size) == 1:
        return size[0], size[0]

    if len(size) != 2:
        raise ValueError(error_msg)

    return size

def _check_sequence_input(x, name, req_sizes):
    msg = req_sizes[0] if len(req_sizes) < 2 else " or ".join([str(s) for s in req_sizes])
    if not isinstance(x, Sequence):
        raise TypeError(f"{name} should be a sequence of length {msg}.")
    if len(x) not in req_sizes:
        raise ValueError(f"{name} should be a sequence of length {msg}.")

def _setup_angle(x, name, req_sizes=(2,)):
    if isinstance(x, numbers.Number):
        if x < 0:
            raise ValueError(f"If {name} is a single number, it must be positive.")
        x = [-x, x]
    else:
        _check_sequence_input(x, name, req_sizes)

    return [float(d) for d in x]

def forward(self, img):
