def describe(self) -> str:
    return (
        "Accepts ``PIL.Image``, batched ``(B, C, H, W)`` and single ``(C, H, W)`` image ``torch.Tensor`` objects. "
        "The images are rescaled to ``[0.0, 1.0]``."
